// src/Component/UserList.js
import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  fetchUsersAsync,
  createUserAsync,
  updateUserAsync,
  deleteUserAsync,
  selectUsersState,
} from "./userSlice";
import "./UserList.css";

function UserList() {
  const dispatch = useDispatch();
  const { users, loading, error } = useSelector(selectUsersState);

  const [editUserId, setEditUserId] = useState(null);
  const [editData, setEditData] = useState({});
  const [showAddForm, setShowAddForm] = useState(false);
  const [newUser, setNewUser] = useState({
    username: "",
    email: "",
    first_name: "",
    last_name: "",
    is_active: true,
    profile: { bio: "", phone: "" },
  });

  useEffect(() => {
    dispatch(fetchUsersAsync());
  }, [dispatch]);

  // --- Handlers ---
  const handleEditClick = (user) => {
    setEditUserId(user.id);
    setEditData({ ...user });
  };

  const handleChange = (key, value, isNew = false) => {
    if (key === "bio" || key === "phone") {
      if (isNew) {
        setNewUser({ ...newUser, profile: { ...newUser.profile, [key]: value } });
      } else {
        setEditData({ ...editData, profile: { ...editData.profile, [key]: value } });
      }
    } else if (key === "is_active") {
      if (isNew) setNewUser({ ...newUser, [key]: value });
      else setEditData({ ...editData, [key]: value });
    } else {
      if (isNew) setNewUser({ ...newUser, [key]: value });
      else setEditData({ ...editData, [key]: value });
    }
  };

  const handleSave = async () => {
    if (!editUserId) return;
    try {
      await dispatch(updateUserAsync(editData)).unwrap();
      await dispatch(fetchUsersAsync());
      setEditUserId(null);
      alert("✅ User updated successfully");
    } catch (err) {
      console.error(err);
      alert("Update failed on backend. Please try again.");
    }
  };

  const handleDelete = async (id) => {
    if (!id) return;
    if (window.confirm("Are you sure you want to delete this user?")) {
      try {
        await dispatch(deleteUserAsync(id)).unwrap();
        await dispatch(fetchUsersAsync());
        alert("User deleted successfully!");
      } catch (err) {
        console.error(err);
        alert("Delete failed: " + err.message);
      }
    }
  };

  const handleAddUser = async () => {
    try {
      await dispatch(createUserAsync(newUser)).unwrap();
      await dispatch(fetchUsersAsync());
      setShowAddForm(false);
      setNewUser({
        username: "",
        email: "",
        first_name: "",
        last_name: "",
        is_active: true,
        profile: { bio: "", phone: "" },
      });
      alert("✅ User added successfully!");
    } catch (err) {
      console.error(err);
      alert("Failed to add user: " + err.message);
    }
  };

  if (loading) return <p>Loading users...</p>;
  if (error) return <p style={{ color: "red" }}>Error: {error}</p>;

  return (
    <div className="userlist-container">
      <h2>User Management</h2>

      {/* Add User Button */}
      <button className="add-user-btn" onClick={() => setShowAddForm(!showAddForm)}>
        {showAddForm ? "Cancel" : "Add User"}
      </button>

      {/* Add User Form */}
      {showAddForm && (
        <div className="add-user-form">
          <input
            type="text"
            placeholder="Username"
            value={newUser.username}
            onChange={(e) => handleChange("username", e.target.value, true)}
          />
          <input
            type="text"
            placeholder="Email"
            value={newUser.email}
            onChange={(e) => handleChange("email", e.target.value, true)}
          />
          <input
            type="text"
            placeholder="First Name"
            value={newUser.first_name}
            onChange={(e) => handleChange("first_name", e.target.value, true)}
          />
          <input
            type="text"
            placeholder="Last Name"
            value={newUser.last_name}
            onChange={(e) => handleChange("last_name", e.target.value, true)}
          />
          <input
            type="text"
            placeholder="Bio"
            value={newUser.profile.bio}
            onChange={(e) => handleChange("bio", e.target.value, true)}
          />
          <input
            type="text"
            placeholder="Phone"
            value={newUser.profile.phone}
            onChange={(e) => handleChange("phone", e.target.value, true)}
          />
          <select
            value={newUser.is_active ? "Active" : "Inactive"}
            onChange={(e) => handleChange("is_active", e.target.value === "Active", true)}
          >
            <option>Active</option>
            <option>Inactive</option>
          </select>
          <button className="save-btn" onClick={handleAddUser}>
            Save
          </button>
        </div>
      )}

      {/* User Table */}
      <table className="user-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Username</th>
            <th>Email</th>
            <th>First Name</th>
            <th>Last Name</th>
            <th>Bio</th>
            <th>Phone</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {users.length > 0 ? (
            users.map((u) => (
              <tr key={u.id}>
                <td>{u.id}</td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.username || ""}
                      onChange={(e) => handleChange("username", e.target.value)}
                    />
                  ) : (
                    u.username
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.email || ""}
                      onChange={(e) => handleChange("email", e.target.value)}
                    />
                  ) : (
                    u.email
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.first_name || ""}
                      onChange={(e) => handleChange("first_name", e.target.value)}
                    />
                  ) : (
                    u.first_name
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.last_name || ""}
                      onChange={(e) => handleChange("last_name", e.target.value)}
                    />
                  ) : (
                    u.last_name
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.profile?.bio || ""}
                      onChange={(e) => handleChange("bio", e.target.value)}
                    />
                  ) : (
                    u.profile?.bio || ""
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <input
                      type="text"
                      value={editData.profile?.phone || ""}
                      onChange={(e) => handleChange("phone", e.target.value)}
                    />
                  ) : (
                    u.profile?.phone || ""
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <select
                      value={editData.is_active ? "Active" : "Inactive"}
                      onChange={(e) =>
                        handleChange("is_active", e.target.value === "Active")
                      }
                    >
                      <option>Active</option>
                      <option>Inactive</option>
                    </select>
                  ) : u.is_active ? (
                    "Active"
                  ) : (
                    "Inactive"
                  )}
                </td>
                <td>
                  {editUserId === u.id ? (
                    <>
                      <button className="save-btn" onClick={handleSave}>
                        Save
                      </button>
                      <button
                        className="cancel-btn"
                        onClick={() => setEditUserId(null)}
                      >
                        Cancel
                      </button>
                    </>
                  ) : (
                    <>
                      <button
                        className="edit-btn"
                        onClick={() => handleEditClick(u)}
                      >
                        Edit
                      </button>
                      <button
                        className="delete-btn"
                        onClick={() => handleDelete(u.id)}
                      >
                        Delete
                      </button>
                    </>
                  )}
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="9" style={{ textAlign: "center" }}>
                No users found
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

export default UserList;
